// Renders Clai brand exports from assets/branding/source (generated by assets/branding/generate.py).
//   node scripts/build-brand.mjs
// Outputs:
//   assets/branding/exports/*.png     transparent PNGs of every mark/wordmark/lockup variant
//   assets/branding/social/*.png      GitHub (1280×640), X and LinkedIn (1200×630) previews
//   frontend/app/{favicon.ico,icon.svg,apple-icon.png,opengraph-image.png,twitter-image.png}
//   frontend/public/{icon-192.png,icon-512.png,brand/*.svg}
import { copyFileSync, mkdirSync, readFileSync, readdirSync, rmSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { chromium } from "@playwright/test";

const root = join(dirname(fileURLToPath(import.meta.url)), "..", "..");
const brand = join(root, "assets", "branding");
const src = join(brand, "source");
const exportsDir = join(brand, "exports");
const socialDir = join(brand, "social");
const appDir = join(root, "frontend", "app");
const publicDir = join(root, "frontend", "public");
rmSync(exportsDir, { recursive: true, force: true });
for (const d of [exportsDir, socialDir, join(publicDir, "brand")]) mkdirSync(d, { recursive: true });

const svg = (name) => readFileSync(join(src, name), "utf8");
const b64 = (path) => readFileSync(path).toString("base64");
const dataUri = (s) => `data:image/svg+xml;base64,${Buffer.from(s).toString("base64")}`;
const ratio = (name) => {
  const [, , w, h] = svg(name).match(/viewBox="([\d.\s-]+)"/)[1].trim().split(/\s+/).map(Number);
  return w / h;
};

const browser = await chromium.launch({ channel: process.env.CI ? undefined : "chrome" });
const page = await browser.newPage();

async function renderSvg(svgText, width, height, out) {
  await page.setViewportSize({ width, height });
  await page.setContent(`<html><body style="margin:0;background:transparent"><img src="${dataUri(svgText)}" style="width:${width}px;height:${height}px;display:block"></body></html>`);
  await page.locator("img").evaluate((img) => img.decode());
  await page.screenshot({ path: out, omitBackground: true, clip: { x: 0, y: 0, width, height } });
}

// ── Transparent exports ──────────────────────────────────────────────
for (const name of readdirSync(src).filter((f) => f.endsWith(".svg"))) {
  const text = svg(name).replaceAll("currentColor", name.includes("mono") ? "#0C0E0D" : "currentColor");
  const h = name.startsWith("mark") || name.includes("icon") || name.includes("favicon") ? 512 : 192;
  await renderSvg(text, Math.round(h * ratio(name)), h, join(exportsDir, name.replace(".svg", ".png")));
  copyFileSync(join(src, name), join(publicDir, "brand", name));
}

// ── App icons ────────────────────────────────────────────────────────
const ico = [];
for (const s of [16, 32, 48]) {
  const out = join(exportsDir, `favicon-${s}.png`);
  await renderSvg(svg("favicon.svg"), s, s, out);
  ico.push({ size: s, data: readFileSync(out) });
}
writeFileSync(join(appDir, "favicon.ico"), buildIco(ico));
copyFileSync(join(src, "favicon.svg"), join(appDir, "icon.svg"));
await renderSvg(svg("app-icon.svg").replace('rx="14"', 'rx="0"'), 180, 180, join(appDir, "apple-icon.png"));
await renderSvg(svg("app-icon.svg"), 192, 192, join(publicDir, "icon-192.png"));
await renderSvg(svg("app-icon.svg"), 512, 512, join(publicDir, "icon-512.png"));

// ── Social previews ──────────────────────────────────────────────────
const fonts = join(brand, "fonts");
const card = (width, height) => `<!doctype html><html><head><style>
@font-face{font-family:News;src:url(data:font/ttf;base64,${b64(join(fonts, "Newsreader-Regular.ttf"))})}
@font-face{font-family:NewsI;src:url(data:font/ttf;base64,${b64(join(fonts, "Newsreader-Italic.ttf"))})}
@font-face{font-family:Mono;src:url(data:font/ttf;base64,${b64(join(fonts, "GeistMono-Regular.ttf"))})}
*{box-sizing:border-box;margin:0}
body{width:${width}px;height:${height}px;background:#0C0E0D;color:#F2F1EC;position:relative;overflow:hidden}
.rule{position:absolute;left:0;right:0;height:1px;background:#262C28}
.logo{position:absolute;left:80px;top:72px;height:44px}
h1{position:absolute;left:80px;bottom:150px;font-family:News;font-weight:400;font-size:88px;line-height:1;letter-spacing:-0.02em}
h1 em{font-family:NewsI;font-style:normal;color:#B8D9C6}
.meta{position:absolute;left:80px;bottom:72px;font-family:Mono;font-size:19px;letter-spacing:.06em;color:#7A827C}
.doc{position:absolute;right:80px;top:72px;width:340px;padding:26px 28px;border:1px solid #2A302C;background:#121513;font-family:Mono;font-size:15px;line-height:1.75;color:#7A827C}
.doc b{display:block;font-weight:400;color:#A9AEA8;margin-bottom:10px}
.doc mark{background:none;color:#0C0E0D;box-shadow:inset 0 -1.15em 0 #B8D9C6}
</style></head><body>
<img class="logo" src="${dataUri(svg("logo.svg"))}">
<div class="doc"><b>8. Termination</b>8.1 Either party may terminate<br>this agreement with <mark>30 days'</mark><br><mark>written notice</mark>.</div>
<div class="rule" style="top:${height - 116}px"></div>
<h1>Your agreement, <em>explained.</em></h1>
<p class="meta">ASK · LISTEN · TRACE IT TO THE CLAUSE</p>
</body></html>`;

async function renderHtml(html, width, height, out) {
  await page.setViewportSize({ width, height });
  await page.setContent(html);
  await page.evaluate(() => document.fonts.ready);
  await page.screenshot({ path: out, clip: { x: 0, y: 0, width, height } });
}
await renderHtml(card(1200, 630), 1200, 630, join(appDir, "opengraph-image.png"));
for (const name of ["twitter-image.png"]) copyFileSync(join(appDir, "opengraph-image.png"), join(appDir, name));
copyFileSync(join(appDir, "opengraph-image.png"), join(socialDir, "x-card.png"));
copyFileSync(join(appDir, "opengraph-image.png"), join(socialDir, "linkedin-share.png"));
await renderHtml(card(1280, 640), 1280, 640, join(socialDir, "github-social-preview.png"));

await browser.close();
console.log("brand assets written");

/** Minimal ICO writer with PNG-compressed entries. */
function buildIco(images) {
  const header = Buffer.alloc(6);
  header.writeUInt16LE(0, 0);
  header.writeUInt16LE(1, 2);
  header.writeUInt16LE(images.length, 4);
  let offset = 6 + 16 * images.length;
  const entries = images.map(({ size, data }) => {
    const e = Buffer.alloc(16);
    e.writeUInt8(size, 0);
    e.writeUInt8(size, 1);
    e.writeUInt16LE(1, 4);
    e.writeUInt16LE(32, 6);
    e.writeUInt32LE(data.length, 8);
    e.writeUInt32LE(offset, 12);
    offset += data.length;
    return e;
  });
  return Buffer.concat([header, ...entries, ...images.map((i) => i.data)]);
}
